/**
 * TSL helper for applying indirect batched transforms to vertices.
 * Automatically resolves instance IDs, applies transforms, and handles geometry masking.
 *
 * **Example: Basic setup**
 *
 * ```js
 * import * as THREE from 'three/webgpu';
 * import { IndirectBatchedMesh, indirectBatch } from '@three-blocks/core';
 * import { positionLocal, morphReference, skinning, uniform, subBuild, normalLocal, Fn } from 'three/tsl';
 *
 * const geometry = new THREE.BoxGeometry(1, 1, 1);
 * const vertexCount = geometry.getAttribute('position').count;
 * const indexCount = geometry.getIndex()?.count || 0;
 * const instanceCount = 512;
 *
 * const material = new THREE.MeshBasicNodeMaterial();
 * const mesh = new IndirectBatchedMesh(instanceCount, vertexCount, indexCount, material);
 *
 * // Disable internal culling for this simple demo
 * mesh.perObjectFrustumCulled = false;
 *
 * const geoId = mesh.addGeometry(geometry);
 *
 * // Setup the indirect batch transform
 * material.setupPosition = function(builder) {
 *   const { object, geometry } = builder;
 *
 *   if (geometry.morphAttributes.position || geometry.morphAttributes.normal || geometry.morphAttributes.color) {
 *     morphReference(object).toStack();
 *   }
 *
 *   if (object.isSkinnedMesh === true) {
 *     skinning(object).toStack();
 *   }
 *
 *   if (object.isIndirectBatchedMesh) {
 *     // inject here
 *     indirectBatch(object).toStack();
 *
 *     const worldMatrix = uniform(new THREE.Matrix4()).onObjectUpdate((_, self) => self.value.copy(object.matrixWorld)).setName('batchWorldMatrix');
 *     object.setCullingMatrixNode(({ baseMatrix }) => worldMatrix.mul(baseMatrix));
 *   }
 *
 *   if (this.positionNode !== null) {
 *     positionLocal.assign(subBuild(this.positionNode, 'POSITION', 'vec3'));
 *   }
 *
 *   return positionLocal;
 * };
 *
 * // Use normal-based coloring to verify transforms work correctly
 * material.colorNode = Fn(() => {
 *   return normalLocal.mul(0.5).add(0.5);
 * })();
 *
 * // Add instances in a grid pattern
 * const tmpMatrix = new THREE.Matrix4();
 * const gridSize = Math.ceil(Math.cbrt(instanceCount));
 * const spacing = 2.5;
 *
 * let idx = 0;
 * for (let x = 0; x < gridSize && idx < instanceCount; x++) {
 *   for (let y = 0; y < gridSize && idx < instanceCount; y++) {
 *     for (let z = 0; z < gridSize && idx < instanceCount; z++) {
 *       const id = mesh.addInstance(geoId);
 *       tmpMatrix.makeTranslation(
 *         (x - gridSize / 2) * spacing,
 *         (y - gridSize / 2) * spacing,
 *         (z - gridSize / 2) * spacing
 *       );
 *       mesh.setMatrixAt(id, tmpMatrix);
 *       idx++;
 *     }
 *   }
 * }
 *
 * mesh.needsUpdate = true;
 * ```
 *
 * @function indirectBatch
 * @short TSL node that applies IndirectBatchedMesh transforms and geometry masking to vertex data.
 * @category IndirectBatchedMesh
 * @tags WebGPU
 * @tsl
 * @demo docs/demos/indirect-batch.html
 * @param {IndirectBatchedMesh} batchMesh The batched mesh instance to read data from.
 * @returns {IndirectBatchNode} Node that transforms vertices using batched instance data.
 */
export const indirectBatch: any;
export function indirectBatchId(batchMesh: IndirectBatchedMesh): Node<int>;
/**
 * Access the per-instance color written by {@link IndirectBatchNode}.
 *
 * This node reads the varying `vBatchColor` populated automatically when:
 * - `IndirectBatchedMesh.setColorAt()` is called, and
 * - the material uses `indirectBatch(mesh)` (so the varying is assigned).
 *
 * Works in both vertex and fragment stages.
 *
 * @example
 * import * as THREE from 'three/webgpu';
 * import { IndirectBatchedMesh, indirectBatch, indirectBatchColor } from '@three-blocks/core';
 * import { diffuseColor, materialColor, normalLocal, vec4 } from 'three/tsl';
 *
 * const geometry = new THREE.BoxGeometry(1.2, 1.2, 1.2);
 * const vertexCount = geometry.getAttribute('position').count;
 * const indexCount = geometry.getIndex()?.count || 0;
 * const instanceCount = 300;
 *
 * const material = new THREE.MeshBasicNodeMaterial();
 * const mesh = new IndirectBatchedMesh(instanceCount, vertexCount, indexCount, material);
 *
 * mesh.perObjectFrustumCulled = false;
 * const geoId = mesh.addGeometry(geometry);
 *
 * material.colorNode = vec4(materialColor.rgb.add(normalLocal.normalize().mul(0.5)), 1.0);
 *
 * const originalSetupDiffuseColor = material.setupDiffuseColor ? material.setupDiffuseColor.bind(material) : null;
 * material.setupDiffuseColor = function(builder) {
 *   // Run original setupDiffuseColor first (handles user colorNode, vertexColors, etc.)
 *   if (originalSetupDiffuseColor) {
 *     originalSetupDiffuseColor(builder);
 *   }
 *
 *   // override diffuseColor with batchedTextColor
 *   diffuseColor.rgb.assign(indirectBatchColor.mul(diffuseColor.rgb));
 * };
 *
 * // Add instances with different colors
 * const tmpMatrix = new THREE.Matrix4();
 * const tmpPosition = new THREE.Vector3();
 * const tmpQuat = new THREE.Quaternion();
 * const tmpEuler = new THREE.Euler();
 * const tmpScale = new THREE.Vector3();
 * const color = new THREE.Color();
 *
 * for (let i = 0; i < instanceCount; i++) {
 *   const id = mesh.addInstance(geoId);
 *
 *   tmpEuler.set(Math.random() * Math.PI, Math.random() * Math.PI, Math.random() * Math.PI);
 *   tmpQuat.setFromEuler(tmpEuler);
 *   tmpScale.setScalar(0.7 + Math.random() * 0.5);
 *   tmpPosition.set((Math.random() - 0.5) * 35, (Math.random() - 0.5) * 35, (Math.random() - 0.5) * 35);
 *   tmpMatrix.compose(tmpPosition, tmpQuat, tmpScale);
 *   mesh.setMatrixAt(id, tmpMatrix);
 *
 *   // Set per-instance color using HSL for nice distribution
 *   mesh.setColorAt(id, color.setHSL(i / instanceCount, 0.7, 0.55));
 * }
 *
 * mesh.needsUpdate = true;
 *
 * @function indirectBatchColor
 * @category IndirectBatchedMesh
 * @tags WebGPU
 * @tsl
 * @demo docs/demos/indirect-batch-color.html
 * @returns {Node<vec3>} Per-instance color varying.
 */
export const indirectBatchColor: any;
export function indirectBatchMatrix(batchMesh: IndirectBatchedMesh, idNode?: Node<int>): Node<mat4>;
export function indirectBatchGeometryId(batchMesh: IndirectBatchedMesh, idNode?: Node<int>): Node<int>;
